CREATE TABLE accounts (
    account_id SERIAL PRIMARY KEY,
    account_name VARCHAR(255) NOT NULL UNIQUE,
    balance DECIMAL(10, 2),
    debit_balance DECIMAL(10, 2),
    credit_balance DECIMAL(10, 2)
);

CREATE TRIGGER update_balance AFTER INSERT OR UPDATE ON transactions FOR EACH ROW EXECUTE FUNCTION update_account_balance();

CREATE FUNCTION update_account_balance() RETURNS TRIGGER AS $$
BEGIN
    IF NEW.debit THEN
        UPDATE accounts SET debit_balance = debit_balance + NEW.amount WHERE account_id = NEW.account_id;
    ELSE
        UPDATE accounts SET credit_balance = credit_balance + NEW.amount WHERE account_id = NEW.account_id;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE INDEX idx_accounts_balance ON accounts(debit_balance);
CREATE INDEX idx_accounts_credit_balance ON accounts(credit_balance);

